package stream

import (
	"context"
	"log/slog"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// TestPackFlowLog pins the pack flow's log vocabulary (pack-manifest-audio
// D7): Pack reads from logs alone — ONE "streams: pack published" INFO line at
// the success return carrying item, nonce, layout (single-variant |
// rendition), variants, audio (the composed master's EXT-X-MEDIA member
// count), codecs (recorded | degraded), and probes (the actual ffprobe
// invocation count); ONE "streams: pack failed" WARN naming the failing stage
// on any error; no per-segment lines ever; and INV4 holds (item id and nonce
// are artifact identifiers — no token, no play URL).
func TestPackFlowLog(t *testing.T) {
	ctx := context.Background()

	// captureLog swaps the default slog logger for a fresh logBuffer for the
	// test's duration (the only sink the flow lines write to).
	captureLog := func(t *testing.T) *logBuffer {
		t.Helper()
		buf := &logBuffer{}
		prev := slog.Default()
		slog.SetDefault(slog.New(buf))
		t.Cleanup(func() { slog.SetDefault(prev) })
		return buf
	}

	t.Run("published_single_variant", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second) // whole file IS the head chunk
		buf := captureLog(t)

		build, err := s.Pack(ctx, "it_flow1", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}

		lines := flowLines(buf, "streams: pack published")
		if len(lines) != 1 {
			t.Fatalf("got %d published lines, want exactly ONE (D7):\n%s", len(lines), buf)
		}
		line := lines[0]
		for key, want := range map[string]string{
			"item":     "it_flow1",
			"nonce":    build.Nonce,
			"layout":   "single-variant",
			"variants": "1",
			"audio":    "0",        // the single-variant master carries no EXT-X-MEDIA group
			"codecs":   "degraded", // mpeg4 composes no RFC 6381 string — the record fails open to nil
		} {
			if got := logField(line, key); got != want {
				t.Fatalf("published line %s = %q, want %q:\n%s", key, got, want, line)
			}
		}
		if n, want := logField(line, "probes"), "1"; n != want {
			t.Fatalf("published line probes = %q, want %q (one ffprobe, the one variant):\n%s", n, want, line)
		}
		// ONE line for the whole flow — no per-segment chatter.
		if lines := strings.Count(strings.TrimRight(buf.String(), "\n"), "\n") + 1; lines != 1 {
			t.Fatalf("Pack logged %d lines, want exactly the one published line:\n%s", lines, buf)
		}
		assertINV4(t, buf)
	})

	t.Run("published_rendition", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeH264Fixture(t, dir, 12*time.Second)
		v1 := makeVoiceover(t, dir, "rus1.mka", 600, 12*time.Second)
		v2 := makeVoiceover(t, dir, "rus2.mka", 800, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second) // head 5s + tail 7s: both phases run
		buf := captureLog(t)

		build, err := s.Pack(ctx, "it_flow2", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}},
			[]string{v1, v2})
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}

		lines := flowLines(buf, "streams: pack published")
		if len(lines) != 1 {
			t.Fatalf("got %d published lines, want exactly ONE (D7):\n%s", len(lines), buf)
		}
		line := lines[0]
		for key, want := range map[string]string{
			"item":     "it_flow2",
			"nonce":    build.Nonce,
			"layout":   "rendition",
			"variants": "4",        // rend0 video + rend1 embedded + 2 voiceovers
			"audio":    "3",        // the composed master's EXT-X-MEDIA TYPE=AUDIO members
			"codecs":   "recorded", // h264+aac compose RFC 6381 strings
		} {
			if got := logField(line, key); got != want {
				t.Fatalf("published line %s = %q, want %q:\n%s", key, got, want, line)
			}
		}
		if n, want := logField(line, "probes"), "4"; n != want {
			t.Fatalf("published line probes = %q, want %q (one ffprobe per variant):\n%s", n, want, line)
		}
		assertINV4(t, buf)
	})

	t.Run("failed_names_the_stage", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)
		s.FFmpeg = filepath.Join(dir, "no-such-ffmpeg") // the head phase never starts
		buf := captureLog(t)

		if _, err := s.Pack(ctx, "it_flow3", fixture, nil, nil); err == nil {
			t.Fatal("Pack succeeded without ffmpeg; want an error")
		}
		if lines := flowLines(buf, "streams: pack published"); len(lines) != 0 {
			t.Fatalf("a failed pack logged a published line:\n%s", buf)
		}
		lines := flowLines(buf, "streams: pack failed")
		if len(lines) != 1 {
			t.Fatalf("got %d failed lines, want exactly ONE WARN (D7):\n%s", len(lines), buf)
		}
		line := lines[0]
		if got, want := logField(line, "item"), "it_flow3"; got != want {
			t.Fatalf("failed line item = %q, want %q:\n%s", got, want, line)
		}
		if got, want := logField(line, "stage"), "ffmpeg-head"; got != want {
			t.Fatalf("failed line stage = %q, want %q:\n%s", got, want, line)
		}
		assertINV4(t, buf)
	})

	t.Run("failed_tail_names_its_stage", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)           // head 5s + tail 7s: both phases run
		s.afterHead = func(string) { s.FFmpeg = filepath.Join(dir, "no-such-ffmpeg") } // the tail phase never starts
		buf := captureLog(t)

		if _, err := s.Pack(ctx, "it_flow4", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil); err == nil {
			t.Fatal("Pack succeeded with a broken tail ffmpeg; want an error")
		}
		lines := flowLines(buf, "streams: pack failed")
		if len(lines) != 1 {
			t.Fatalf("got %d failed lines, want exactly ONE WARN (D7):\n%s", len(lines), buf)
		}
		if got, want := logField(lines[0], "stage"), "ffmpeg-tail"; got != want {
			t.Fatalf("failed line stage = %q, want %q:\n%s", got, want, lines[0])
		}
	})
}

// flowLines returns the buffer's lines whose message is msg (the logBuffer
// renders "message key=value ...").
func flowLines(buf *logBuffer, msg string) []string {
	var out []string
	for _, line := range strings.Split(strings.TrimRight(buf.String(), "\n"), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		if line == msg || strings.HasPrefix(line, msg+" ") {
			out = append(out, line)
		}
	}
	return out
}

// logField returns the value of key in a logBuffer-rendered line ("" when
// absent). Only reliable for space-free values — the flow vocabulary's are.
func logField(line, key string) string {
	for _, f := range strings.Fields(line) {
		if k, v, ok := strings.Cut(f, "="); ok && k == key {
			return v
		}
	}
	return ""
}

// assertINV4 pins the identifier discipline over the whole capture: no token
// material and no play URL (the media prefix) ever reaches a pack flow line —
// item ids and nonces are the only identifiers the flow logs (D7).
func assertINV4(t *testing.T, buf *logBuffer) {
	t.Helper()
	if s := buf.String(); strings.Contains(s, "token=") || strings.Contains(s, mediaPrefix+"/") {
		t.Fatalf("pack flow log carries token or play-URL material (INV4):\n%s", s)
	}
}
